package com.taskly.recruitment;
import jakarta.validation.constraints.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service
public class RecruitmentUniformService {
 public record Package(UUID id,String name,String description,long price,String policy,boolean active,long version,Map<String,Integer> sizes,String imageUrl,List<Map<String,String>> items) {}
 public record PackageWrite(@NotBlank @Size(max=160) String name,@NotBlank @Size(max=2000) String description,@Min(0) @Max(100000000) long price,@NotBlank @Size(max=2000) String policy,boolean active,@PositiveOrZero long version,@NotEmpty @Size(max=10) Map<@Pattern(regexp="XS|S|M|L|XL|XXL|XXXL") String,@Min(0) @Max(100000) Integer> sizes,@Size(max=3000000) String imageUrl,@Size(max=12) List<Map<String,String>> items) { public PackageWrite(String name,String description,long price,String policy,boolean active,long version,Map<String,Integer> sizes){this(name,description,price,policy,active,version,sizes,null,List.of());} }
 public record OrderWrite(@NotNull UUID packageId,@NotBlank String size,@Pattern(regexp="ONLINE|AT_OFFICE") String paymentMethod,@NotBlank @Size(max=100) String requestId) {}
 public record Payment(@NotNull @Pattern(regexp="SUCCESS|FAILURE") String result) {}
 public record Adjustment(@NotNull @Pattern(regexp="REFUND|EXCHANGE|HANDOVER") String action,@Pattern(regexp="XS|S|M|L|XL|XXL|XXXL") String size,boolean originalsReturned,@NotBlank @Size(max=1000) String reason,@NotBlank @Size(max=100) String requestId) {}
 @Transactional public Map<String,Object> adjust(UUID actor,UUID id,Adjustment w){
  if(!w.action().equals("HANDOVER")&&!Set.of("test","local","dev","development").contains(environment))throw RecruitmentService.invalid("Hoàn/đổi DEMO chỉ bật ở development/test.");
  var found=db.queryForList("SELECT a.user_id FROM partner_uniform_orders o JOIN partner_applications a ON a.id=o.application_id WHERE o.id=?",UUID.class,id);if(found.isEmpty())throw RecruitmentService.invalid("Không tìm thấy đơn đồng phục.");
  var app=recruitment.current(found.getFirst());String hash=RecruitmentService.hash(id+":"+w.toString());
  var prior=db.queryForList("SELECT payload_hash FROM partner_uniform_adjustments WHERE actor_id=? AND request_key=?",String.class,actor,w.requestId());if(!prior.isEmpty()){if(!prior.getFirst().equals(hash))throw RecruitmentService.conflict();return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);}
  var row=db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=? FOR UPDATE",id);
  if(!Set.of("PAID","WAIVED").contains(row.get("payment_status"))||Set.of("CANCELLED","REFUNDED").contains(row.get("status")))throw RecruitmentService.invalid("Chỉ xử lý đơn đã thanh toán hoặc được miễn phí.");
  db.queryForObject("SELECT id FROM partner_uniform_packages WHERE id=? FOR UPDATE",UUID.class,row.get("package_id"));
  String oldSize=(String)row.get("size");long amount=0;
  if(w.action().equals("HANDOVER")){
   if(row.get("handed_over_at")!=null)throw RecruitmentService.invalid("Đơn đã bàn giao.");
   db.update("UPDATE partner_uniform_orders SET status='HANDED_OVER',handed_over_at=? WHERE id=?",Timestamp.from(Instant.now()),id);
  }else{
   if(row.get("handed_over_at")!=null&&!w.originalsReturned())throw RecruitmentService.invalid("Xác nhận đã nhận lại đồng phục trước khi hoàn/đổi.");
   if(w.action().equals("EXCHANGE")){
    if(w.size()==null||w.size().equals(oldSize))throw RecruitmentService.invalid("Chọn kích thước mới khác kích thước hiện tại.");
    if(db.update("UPDATE partner_uniform_inventory SET stock=stock-1 WHERE package_id=? AND size=? AND stock>0",row.get("package_id"),w.size())!=1)throw RecruitmentService.invalid("Kích thước mới hết hàng.");
    db.update("UPDATE partner_uniform_orders SET size=?,status='RESERVED',handed_over_at=NULL WHERE id=?",w.size(),id);
   }else{
    amount="PAID".equals(row.get("payment_status"))?((Number)row.get("price")).longValue():0;
    db.update("UPDATE partner_uniform_orders SET status='REFUNDED',payment_status='REFUNDED' WHERE id=?",id);
    boolean resolved=db.queryForObject("SELECT COUNT(*) FROM partner_uniform_orders WHERE application_id=? AND payment_status IN ('PAID','WAIVED') AND status NOT IN ('CANCELLED','REFUNDED')",Integer.class,app.id())>0;
    db.update("UPDATE partner_applications SET uniform_resolved=?,status=?,version=version+1,updated_at=? WHERE id=?",resolved,app.status().equals("ACTIVE")&&!resolved?"SUSPENDED":app.status(),Timestamp.from(Instant.now()),app.id());
   }
   if(db.update("UPDATE partner_uniform_inventory SET stock=stock+1 WHERE package_id=? AND size=?",row.get("package_id"),oldSize)==0)db.update("INSERT INTO partner_uniform_inventory VALUES(?,?,1)",row.get("package_id"),oldSize);
  }
  String reason=w.reason().replaceAll("[0-9]{8,}","[đã ẩn]").replaceAll("[^\\s]+@[^\\s]+","[email đã ẩn]");
  db.update("INSERT INTO partner_uniform_adjustments VALUES(?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),id,actor,w.action(),reason,w.requestId(),hash,oldSize,w.size(),amount,Timestamp.from(Instant.now()));
  recruitment.audit(actor,app.id(),"UNIFORM_"+w.action()+"_DEMO",null,null,"Đơn "+id+"; tiền mô phỏng "+amount+"; "+reason);
  if(w.action().equals("HANDOVER"))review.notify(app.id(),"Bạn đã nhận đồng phục TaskLy!","Nhân viên đã xác nhận bàn giao đồng phục cho bạn. Vui lòng kiểm tra kích thước và số lượng; nếu cần hỗ trợ, hãy trao đổi với nhân viên tại văn phòng. Hoàn tất đối chiếu giấy tờ và chờ phê duyệt chính thức để tiếp tục kích hoạt ứng dụng.");
  return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);
 }
 private final JdbcTemplate db;private final RecruitmentService recruitment;private final RecruitmentReviewService review;private final String environment;
 public RecruitmentUniformService(JdbcTemplate db,RecruitmentService recruitment,RecruitmentReviewService review,@Value("${app.environment:production}") String environment){this.db=db;this.recruitment=recruitment;this.review=review;this.environment=environment;}
 public List<Package> catalog(){return db.query("SELECT * FROM partner_uniform_packages ORDER BY price,id",(r,n)->{Map<String,Integer> sizes=new LinkedHashMap<>();db.query("SELECT size,stock FROM partner_uniform_inventory WHERE package_id=? ORDER BY size",rs->{sizes.put(rs.getString(1),rs.getInt(2));},r.getObject("id",UUID.class));return new Package(r.getObject("id",UUID.class),r.getString("name"),r.getString("description"),r.getLong("price"),r.getString("policy"),r.getBoolean("active"),r.getLong("version"),sizes,r.getString("image_url"),new tools.jackson.databind.ObjectMapper().readValue(r.getString("items"),new tools.jackson.core.type.TypeReference<List<Map<String,String>>>(){}));});}
 @Transactional public Package save(UUID actor,UUID id,PackageWrite w){var existing=catalog().stream().filter(p->p.id().equals(id)).findFirst();if(existing.isPresent()){if(db.update("UPDATE partner_uniform_packages SET name=?,description=?,price=?,policy=?,active=?,version=version+1 WHERE id=? AND version=?",w.name(),w.description(),w.price(),w.policy(),w.active(),id,w.version())!=1)throw RecruitmentService.conflict();}else{if(w.version()!=0)throw RecruitmentService.conflict();db.update("INSERT INTO partner_uniform_packages(id,name,description,price,policy,active,version) VALUES(?,?,?,?,?,?,0)",id,w.name(),w.description(),w.price(),w.policy(),w.active());}db.update("UPDATE partner_uniform_packages SET image_url=?,items=? WHERE id=?",w.imageUrl(),new tools.jackson.databind.ObjectMapper().writeValueAsString(w.items()==null?List.of():w.items()),id);db.update("DELETE FROM partner_uniform_inventory WHERE package_id=?",id);w.sizes().forEach((size,stock)->db.update("INSERT INTO partner_uniform_inventory VALUES(?,?,?)",id,size,stock));recruitment.audit(actor,null,"UNIFORM_CATALOG_UPDATED",null,null,"Gói "+id+" giá "+w.price());return catalog().stream().filter(p->p.id().equals(id)).findFirst().orElseThrow();}
 public List<Map<String,Object>> orders(UUID user){var app=recruitment.current(user);return db.queryForList("SELECT o.*,p.name AS package_name FROM partner_uniform_orders o JOIN partner_uniform_packages p ON p.id=o.package_id WHERE o.application_id=? ORDER BY o.created_at DESC",app.id());}
 @Transactional public Map<String,Object> chooseCash(UUID user,UUID id){var app=recruitment.current(user);var rows=db.queryForList("SELECT * FROM partner_uniform_orders WHERE id=? AND application_id=? FOR UPDATE",id,app.id());if(rows.isEmpty())throw RecruitmentService.invalid("Không tìm thấy đơn hàng.");var row=rows.getFirst();if(!"RESERVED".equals(row.get("status"))||Set.of("PAID","WAIVED").contains(row.get("payment_status")))throw RecruitmentService.invalid("Chỉ đổi hình thức thanh toán cho đơn chưa thanh toán.");if("AT_OFFICE".equals(row.get("payment_method")))return row;db.update("UPDATE partner_uniform_orders SET payment_method='AT_OFFICE',payment_status='PENDING' WHERE id=?",id);db.update("UPDATE partner_applications SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",app.id());recruitment.audit(user,app.id(),"UNIFORM_PAYMENT_METHOD_CHANGED",null,null,"Chọn thanh toán tiền mặt tại văn phòng cho đơn "+id);return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);}
 public List<Map<String,Object>> queue(){return db.queryForList("SELECT o.*,p.name AS package_name,a.full_name AS partner_name,a.contact_phone FROM partner_uniform_orders o JOIN partner_uniform_packages p ON p.id=o.package_id JOIN partner_applications a ON a.id=o.application_id ORDER BY o.created_at DESC LIMIT 200");}
 @Transactional public Map<String,Object> order(UUID user,OrderWrite w){var a=recruitment.current(user);if(!a.eligibility().get("preliminary_approved"))throw RecruitmentService.invalid("Chỉ chọn đồng phục sau khi được duyệt sơ bộ.");var prior=db.queryForList("SELECT * FROM partner_uniform_orders WHERE application_id=? AND request_key=?",a.id(),w.requestId());if(!prior.isEmpty()){var row=prior.getFirst();if(!w.packageId().equals(row.get("package_id"))||!w.size().equals(row.get("size"))||!w.paymentMethod().equals(row.get("payment_method")))throw RecruitmentService.conflict();return row;}
  if(db.queryForObject("SELECT COUNT(*) FROM partner_uniform_orders WHERE application_id=? AND status='RESERVED'",Integer.class,a.id())>=2)throw RecruitmentService.invalid("Bạn chỉ được có tối đa 2 đơn đồng phục đang xử lý. Vui lòng nhận hoặc hủy một đơn trước khi đặt thêm.");
  var packages=db.queryForList("SELECT id FROM partner_uniform_packages WHERE id=? AND active=true FOR UPDATE",UUID.class,w.packageId());if(packages.isEmpty())throw RecruitmentService.invalid("Gói không còn hoạt động.");var p=catalog().stream().filter(x->x.id().equals(w.packageId())).findFirst().orElseThrow();
  if(db.update("UPDATE partner_uniform_inventory SET stock=stock-1 WHERE package_id=? AND size=? AND stock>0",w.packageId(),w.size())!=1)throw RecruitmentService.invalid("Kích thước đã hết hàng.");var id=UUID.randomUUID();boolean free=p.price()==0;
  db.update("INSERT INTO partner_uniform_orders(id,application_id,package_id,package_version,size,price,payment_method,payment_status,status,request_key,created_at) VALUES(?,?,?,?,?,?,?,?,'RESERVED',?,?)",id,a.id(),p.id(),p.version(),w.size(),p.price(),w.paymentMethod(),free?"WAIVED":"PENDING",w.requestId(),Timestamp.from(Instant.now()));
  String nextStatus = "ACTIVE".equals(a.status()) ? "ACTIVE" : "UNIFORM_PENDING";
  db.update("UPDATE partner_applications SET status=?,uniform_resolved=?,version=version+1,updated_at=? WHERE id=?",nextStatus,free || "ACTIVE".equals(a.status()) || Boolean.TRUE.equals(a.eligibility().get("uniform_resolved")),Timestamp.from(Instant.now()),a.id());recruitment.audit(user,a.id(),"UNIFORM_ORDER_CREATED",a.status(),nextStatus,"Đơn "+id);return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);
 }
 @Transactional public Map<String,Object> sandboxPay(UUID user,UUID id,Payment w){if(!Set.of("test","local","dev","development").contains(environment))throw RecruitmentService.invalid("Thanh toán mô phỏng chỉ bật trong môi trường development/test.");var a=recruitment.current(user);var rows=db.queryForList("SELECT * FROM partner_uniform_orders WHERE id=? AND application_id=? FOR UPDATE",id,a.id());if(rows.isEmpty())throw RecruitmentService.invalid("Không tìm thấy đơn hàng.");var row=rows.getFirst();if(!"RESERVED".equals(row.get("status")))throw RecruitmentService.invalid("Đơn không còn chờ thanh toán.");if(Set.of("PAID","WAIVED").contains(row.get("payment_status")))return row;boolean paid=w.result().equals("SUCCESS");db.update("UPDATE partner_uniform_orders SET payment_status=?,receipt_id=? WHERE id=?",paid?"PAID":"FAILED",paid?UUID.randomUUID():null,id);boolean resolved=db.queryForObject("SELECT COUNT(*) FROM partner_uniform_orders WHERE application_id=? AND payment_status IN ('PAID','WAIVED') AND status NOT IN ('CANCELLED','REFUNDED')",Integer.class,a.id())>0;db.update("UPDATE partner_applications SET uniform_resolved=?,version=version+1,updated_at=? WHERE id=?",resolved,Timestamp.from(Instant.now()),a.id());recruitment.audit(user,a.id(),"UNIFORM_PAYMENT_SANDBOX",null,null,paid?"SIMULATED_SUCCESS":"SIMULATED_FAILURE");return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);}
 @Transactional public Map<String,Object> confirmOffice(UUID actor,UUID id){var applicants=db.queryForList("SELECT a.user_id FROM partner_applications a JOIN partner_uniform_orders o ON o.application_id=a.id WHERE o.id=?",UUID.class,id);if(applicants.isEmpty())throw RecruitmentService.invalid("Không tìm thấy đơn hàng.");recruitment.current(applicants.getFirst());var row=db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=? FOR UPDATE",id);if(!"AT_OFFICE".equals(row.get("payment_method"))||!"RESERVED".equals(row.get("status")))throw RecruitmentService.invalid("Đơn không chờ thu tiền tại văn phòng.");if(!Set.of("PAID","WAIVED").contains(row.get("payment_status"))){db.update("UPDATE partner_uniform_orders SET payment_status='PAID',receipt_id=? WHERE id=?",UUID.randomUUID(),id);db.update("UPDATE partner_applications SET uniform_resolved=true,version=version+1 WHERE id=?",row.get("application_id"));recruitment.audit(actor,(UUID)row.get("application_id"),"UNIFORM_OFFICE_PAYMENT_CONFIRMED",null,null,"Biên nhận đơn "+id);}return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);}
 @Transactional public Map<String,Object> cancel(UUID user,UUID id){var a=recruitment.current(user);var row=db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=? AND application_id=? FOR UPDATE",id,a.id());if("CANCELLED".equals(row.get("status")))return row;if(!"RESERVED".equals(row.get("status"))||Set.of("PAID","WAIVED").contains(row.get("payment_status")))throw RecruitmentService.invalid("Đơn đã thanh toán cần bộ phận tài chính xử lý hoàn/đổi.");db.update("UPDATE partner_uniform_orders SET status='CANCELLED' WHERE id=?",id);db.update("UPDATE partner_uniform_inventory SET stock=stock+1 WHERE package_id=? AND size=?",row.get("package_id"),row.get("size"));recruitment.audit(user,a.id(),"UNIFORM_ORDER_CANCELLED",null,null,"Đơn "+id);return db.queryForMap("SELECT * FROM partner_uniform_orders WHERE id=?",id);}
}
